import { Component, OnInit } from '@angular/core';
import { HttpClient } from '@angular/common/http';

@Component({
  selector: 'app-race-condition-fix',
  template: `
    <!-- Add button here -->
  `,
  styleUrls: ['./race-condition-fix.component.css']
})
export class RaceConditionFixComponent implements OnInit {
  userData: any = null;
  isLoading: boolean = false;

  constructor(private http: HttpClient) {}

  ngOnInit() {
    this.userData = null;
    this.isLoading = false;
  }

  fetchUserData() {
    this.isLoading = true;
    this.http.get('https://jsonplaceholder.typicode.com/users/1').subscribe(data => {
      this.userData = data;
      this.isLoading = false;
    });
  }
}

